import express from "express";
import path from "path";
import fs from "fs";
import { createServer as createViteServer } from "vite";
import { db } from "./src/server/database";
import { products, categories, promotions, locations, orderItems, orderItemModifiers, orders, productModifiers, modifierOptions, users } from "./src/server/database/schema";
import { eq } from 'drizzle-orm';
import cookieParser from "cookie-parser";
import bcrypt from "bcryptjs";
import jwt from "jsonwebtoken";

const JWT_SECRET = process.env.JWT_SECRET || "flame_and_crust_secret_key_dev";

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(express.json());
  app.use(cookieParser());

  // API Routes
  
  app.get("/api/tenant-config", (req, res) => {
    try {
      const hostname = req.hostname;
      // Get the subdomain (e.g. papapizza.localhost -> papapizza)
      let tenant = hostname.split('.')[0];
      
      // Default to content.json if accessing via localhost directly or IP
      if (tenant === 'localhost' || tenant === '127') {
        tenant = 'default';
      }
      
      const tenantPath = path.join(process.cwd(), 'tenants', `${tenant}.json`);
      console.log("TENANT REQ:", req.hostname, tenant, tenantPath, fs.existsSync(tenantPath));
      if (fs.existsSync(tenantPath)) {
        res.sendFile(tenantPath);
      } else {
        // Fallback to default content
        res.sendFile(path.join(process.cwd(), 'src/content.json'));
      }
    } catch (e) {
      res.status(500).json({ error: "Tenant not found" });
    }
  });

  app.get("/api/health", (req, res) => {
    res.json({ status: "ok" });
  });

  app.post("/api/auth/login", async (req, res) => {
    const { email, password } = req.body;
    try {
      const u = await db.select().from(users).where(eq(users.email, email)).limit(1);
      if (u.length === 0) {
        return res.status(401).json({ error: "Invalid credentials" });
      }
      const user = u[0];
      const valid = await bcrypt.compare(password, user.passwordHash);
      if (!valid) {
        return res.status(401).json({ error: "Invalid credentials" });
      }

      const token = jwt.sign({ id: user.id, isAdmin: user.isAdmin }, JWT_SECRET, { expiresIn: '7d' });
      res.cookie('token', token, { httpOnly: true, secure: process.env.NODE_ENV === 'production', sameSite: 'strict', maxAge: 7 * 24 * 60 * 60 * 1000 });
      
      res.json({ user: { id: user.id, email: user.email, firstName: user.firstName, lastName: user.lastName, isAdmin: user.isAdmin } });
    } catch (e) {
      res.status(500).json({ error: "Server error" });
    }
  });

  app.post("/api/auth/register", async (req, res) => {
    const { email, password, firstName, lastName } = req.body;
    try {
      const existing = await db.select().from(users).where(eq(users.email, email)).limit(1);
      if (existing.length > 0) {
        return res.status(400).json({ error: "Email already in use" });
      }
      
      const passwordHash = await bcrypt.hash(password, 10);
      const id = `usr_${Math.floor(Math.random() * 1000000)}`;
      await db.insert(users).values({ id, email, passwordHash, firstName, lastName, isAdmin: false });
      
      const token = jwt.sign({ id, isAdmin: false }, JWT_SECRET, { expiresIn: '7d' });
      res.cookie('token', token, { httpOnly: true, secure: process.env.NODE_ENV === 'production', sameSite: 'strict', maxAge: 7 * 24 * 60 * 60 * 1000 });
      
      res.json({ user: { id, email, firstName, lastName, isAdmin: false } });
    } catch (e) {
      res.status(500).json({ error: "Server error" });
    }
  });

  app.post("/api/auth/logout", (req, res) => {
    res.clearCookie('token');
    res.json({ success: true });
  });

  app.get("/api/products", async (req, res) => {
    const allProducts = await db.select().from(products);
    // Note: To return full products with modifiers, we should query them or fetch on demand.
    // For now we will fetch modifiers for all products.
    const allModifiers = await db.select().from(productModifiers);
    const allOptions = await db.select().from(modifierOptions);
    
    const result = allProducts.map(p => {
      const pMods = allModifiers.filter(m => m.productId === p.id).map(m => ({
        ...m,
        options: allOptions.filter(o => o.modifierId === m.id)
      }));
      return { ...p, modifiers: pMods };
    });
    res.json(result);
  });

  app.get("/api/products/:slug", async (req, res) => {
    const p = await db.select().from(products).where(eq(products.slug, req.params.slug)).limit(1);
    if (p.length > 0) {
      const product = p[0];
      const pMods = await db.select().from(productModifiers).where(eq(productModifiers.productId, product.id));
      const modsWithOptions = await Promise.all(pMods.map(async (m) => {
        const opts = await db.select().from(modifierOptions).where(eq(modifierOptions.modifierId, m.id));
        return { ...m, options: opts };
      }));
      res.json({ ...product, modifiers: modsWithOptions });
    } else {
      res.status(404).json({ error: "Product not found" });
    }
  });

  app.get("/api/categories", async (req, res) => {
    const cats = await db.select().from(categories);
    res.json(cats);
  });

  app.get("/api/locations", async (req, res) => {
    const locs = await db.select().from(locations);
    res.json(locs);
  });

  app.post("/api/promotions/validate", async (req, res) => {
    const { code } = req.body;
    const p = await db.select().from(promotions).where(eq(promotions.code, code)).limit(1);
    if (p.length > 0 && p[0].isActive) {
      res.json(p[0]);
    } else {
      res.status(400).json({ error: "Invalid or expired promotion code" });
    }
  });

  app.post("/api/orders", async (req, res) => {
    const { items, customer, fulfillment, total, promotionCode, subtotal, discount, tax, deliveryFee } = req.body;
    const orderId = `ORD-${Math.floor(Math.random() * 100000)}`;
    
    // In a real app we'd insert into db here
    try {
       await db.insert(orders).values({
         id: orderId,
         status: 'received',
         method: fulfillment.address ? 'delivery' : 'pickup',
         guestFirstName: customer.firstName,
         guestLastName: customer.lastName,
         guestEmail: customer.email,
         guestPhone: customer.phone,
         subtotal: subtotal || 0,
         discount: discount || 0,
         tax: tax || 0,
         deliveryFee: deliveryFee || 0,
         total: total || 0,
         promotionCode: promotionCode || null,
         createdAt: new Date(),
       });

       res.json({ success: true, orderId, estimatedTime: "30-45 mins" });
    } catch (e) {
       console.error("Order error", e);
       res.status(500).json({error: "Failed to create order"});
    }
  });

  // Vite middleware for development
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
