import { sqliteTable, text, integer, real } from 'drizzle-orm/sqlite-core';

export const categories = sqliteTable('categories', {
  id: text('id').primaryKey(),
  slug: text('slug').notNull().unique(),
  name: text('name').notNull(),
});

export const products = sqliteTable('products', {
  id: text('id').primaryKey(),
  slug: text('slug').notNull().unique(),
  name: text('name').notNull(),
  categoryId: text('category_id').references(() => categories.id),
  description: text('description').notNull(),
  ingredients: text('ingredients', { mode: 'json' }).$type<string[]>(),
  basePrice: integer('base_price').notNull(),
  image: text('image').notNull(),
  rating: real('rating').notNull(),
  reviewCount: integer('review_count').notNull(),
  calories: integer('calories').notNull(),
  isVegetarian: integer('is_vegetarian', { mode: 'boolean' }).notNull(),
  spicyLevel: integer('spicy_level').notNull(),
  isAvailable: integer('is_available', { mode: 'boolean' }).notNull(),
  isFeatured: integer('is_featured', { mode: 'boolean' }).notNull(),
  badge: text('badge'),
  allergies: text('allergies', { mode: 'json' }).$type<string[]>(),
});

export const productModifiers = sqliteTable('product_modifiers', {
  id: text('id').primaryKey(),
  productId: text('product_id').references(() => products.id),
  name: text('name').notNull(),
  isRequired: integer('is_required', { mode: 'boolean' }).notNull(),
  minSelections: integer('min_selections').notNull(),
  maxSelections: integer('max_selections').notNull(),
});

export const modifierOptions = sqliteTable('modifier_options', {
  id: text('id').primaryKey(),
  modifierId: text('modifier_id').references(() => productModifiers.id),
  name: text('name').notNull(),
  priceAdjustment: integer('price_adjustment').notNull(),
  isDefault: integer('is_default', { mode: 'boolean' }).notNull(),
});

export const promotions = sqliteTable('promotions', {
  id: text('id').primaryKey(),
  code: text('code').notNull().unique(),
  title: text('title').notNull(),
  description: text('description').notNull(),
  discountType: text('discount_type').notNull(),
  discountAmount: integer('discount_amount').notNull(),
  maxDiscount: integer('max_discount'),
  minSubtotal: integer('min_subtotal'),
  isActive: integer('is_active', { mode: 'boolean' }).notNull(),
});

export const locations = sqliteTable('locations', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  address: text('address').notNull(),
  phone: text('phone').notNull(),
  isOpen: integer('is_open', { mode: 'boolean' }).notNull(),
  hours: text('hours').notNull(),
});

export const users = sqliteTable('users', {
  id: text('id').primaryKey(),
  email: text('email').notNull().unique(),
  passwordHash: text('password_hash').notNull(),
  firstName: text('first_name').notNull(),
  lastName: text('last_name').notNull(),
  phone: text('phone'),
  isAdmin: integer('is_admin', { mode: 'boolean' }).notNull().default(false),
});

export const userAddresses = sqliteTable('user_addresses', {
  id: text('id').primaryKey(),
  userId: text('user_id').references(() => users.id),
  address: text('address').notNull(),
  apartment: text('apartment'),
  city: text('city').notNull(),
  postalCode: text('postal_code').notNull(),
  instructions: text('instructions'),
  isDefault: integer('is_default', { mode: 'boolean' }).notNull().default(false),
});

export const orders = sqliteTable('orders', {
  id: text('id').primaryKey(),
  userId: text('user_id').references(() => users.id), // null for guest
  guestEmail: text('guest_email'),
  guestFirstName: text('guest_first_name'),
  guestLastName: text('guest_last_name'),
  guestPhone: text('guest_phone'),
  status: text('status').notNull(), // 'received', 'preparing', 'out', 'completed', 'cancelled'
  method: text('method').notNull(), // 'delivery', 'pickup'
  subtotal: integer('subtotal').notNull(),
  discount: integer('discount').notNull(),
  deliveryFee: integer('delivery_fee').notNull(),
  tax: integer('tax').notNull(),
  total: integer('total').notNull(),
  promotionCode: text('promotion_code'),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
});

export const orderItems = sqliteTable('order_items', {
  id: text('id').primaryKey(),
  orderId: text('order_id').references(() => orders.id),
  productId: text('product_id').notNull(),
  name: text('name').notNull(),
  basePrice: integer('base_price').notNull(),
  quantity: integer('quantity').notNull(),
  specialInstructions: text('special_instructions'),
});

export const orderItemModifiers = sqliteTable('order_item_modifiers', {
  id: text('id').primaryKey(),
  orderItemId: text('order_item_id').references(() => orderItems.id),
  optionName: text('option_name').notNull(),
  priceAdjustment: integer('price_adjustment').notNull(),
});
